import{c as t,Q as o,j as a,m as s}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"10 Lifehacks for Using Claude","description":"","frontmatter":{"url":"https://x.com/0xMoysei/status/2061499731571023994","title":"10 Lifehacks for Using Claude","author":"0xMoysei","archived":"2026-06-02T00:00:00.000Z","handle":"@0xMoysei","published":"2026-06-01T00:00:00.000Z","stats":"119 likes · 14 retweets · 197 bookmarks · 18334 views","type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-01-@0xMoysei-023994.md","filePath":"research/tweets/2026-06-01-@0xMoysei-023994.md","lastUpdated":1780990164000}'),r={name:"research/tweets/2026-06-01-@0xMoysei-023994.md"};function i(n,e,l,d,h,u){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="_10-lifehacks-for-using-claude-—-0xmoysei" tabindex="-1">10 Lifehacks for Using Claude — @0xMoysei <a class="header-anchor" href="#_10-lifehacks-for-using-claude-—-0xmoysei" aria-label="Permalink to &quot;10 Lifehacks for Using Claude — @0xMoysei&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/0xMoysei/status/2061499731571023994" target="_blank" rel="noreferrer">https://x.com/0xMoysei/status/2061499731571023994</a><strong>作者</strong>：0xMoysei（@0xMoysei） <strong>發布日期</strong>：2026-06-01 <strong>收錄日期</strong>：2026-06-02 <strong>類型</strong>：Twitter Article <strong>統計</strong>：119 likes · 14 retweets · 197 bookmarks · 18334 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>You get good results from Claude by doing two things: controlling what it reads, and giving it a way to check its own work. The 10 moves below build on that. Most come from Anthropic&#39;s engineering teams and their docs.</p><hr><h2 id="_1-give-claude-a-memory-file" tabindex="-1">1. Give Claude a memory file <a class="header-anchor" href="#_1-give-claude-a-memory-file" aria-label="Permalink to &quot;1. Give Claude a memory file&quot;">​</a></h2><p>In Claude Code, a CLAUDE.md at your project root loads at the start of every session. Write your build commands and known gotchas into it. On claude.ai, a Project does the same job. Upload your style guide or codebase, add custom instructions, and skip re-explaining yourself every chat.</p><p>Keep it short. For each line, ask whether cutting it would make Claude slip. If not, cut it. Claude ignores a bloated file.</p><p>[圖 1]</p><hr><h2 id="_2-clear-context-between-tasks" tabindex="-1">2. Clear context between tasks <a class="header-anchor" href="#_2-clear-context-between-tasks" aria-label="Permalink to &quot;2. Clear context between tasks&quot;">​</a></h2><p>Claude&#39;s context window holds the whole conversation, and quality drops as it fills. Run /clear in Code, or start a fresh chat on claude.ai, when you move to an unrelated task. Corrected Claude twice on the same bug? Clear the context and rewrite the prompt with what you learned. A short clean session gives you better code than a long cluttered one.</p><p>[圖 2]</p><hr><h2 id="_3-explore-then-plan-then-code" tabindex="-1">3. Explore, then plan, then code <a class="header-anchor" href="#_3-explore-then-plan-then-code" aria-label="Permalink to &quot;3. Explore, then plan, then code&quot;">​</a></h2><p>Let Claude jump straight to code and it often builds the wrong thing. Use plan mode instead: Claude reads the relevant files and writes a plan before it changes anything. Edit the plan, then let it build. Skip the step for one-sentence fixes.</p><p>[圖 3]</p><hr><h2 id="_4-teach-claude-once-with-skills" tabindex="-1">4. Teach Claude once with skills <a class="header-anchor" href="#_4-teach-claude-once-with-skills" aria-label="Permalink to &quot;4. Teach Claude once with skills&quot;">​</a></h2><p>A skill is a folder you drop into .claude/skills/. Put your conventions in a SKILL.md and Claude loads it when a task calls for it. Anthropic runs hundreds of them in production. Spend your effort on the Gotchas section, the real mistakes Claude makes with your code. Write them down and it stops repeating them.</p><p>[圖 4]</p><hr><h2 id="_5-give-claude-a-way-to-check-itself" tabindex="-1">5. Give Claude a way to check itself <a class="header-anchor" href="#_5-give-claude-a-way-to-check-itself" aria-label="Permalink to &quot;5. Give Claude a way to check itself&quot;">​</a></h2><p>Claude stops when the work looks done to it. Hand it a test suite or a screenshot to compare against, and it closes the loop alone: write, run, read the result, fix again. With no check, you turn into the test harness and catch every mistake by hand.</p><p>[圖 5]</p><hr><h2 id="_6-push-research-into-subagents" tabindex="-1">6. Push research into subagents <a class="header-anchor" href="#_6-push-research-into-subagents" aria-label="Permalink to &quot;6. Push research into subagents&quot;">​</a></h2><p>Claude reads dozens of files when it explores a codebase, and each one fills your context. Tell it to use subagents to investigate the question. The subagent works in its own window and reports back a summary, so your main session stays clear for the build.</p><p>[圖 6]</p><hr><h2 id="_7-lock-the-rules-you-can-t-break-with-hooks" tabindex="-1">7. Lock the rules you can&#39;t break with hooks <a class="header-anchor" href="#_7-lock-the-rules-you-can-t-break-with-hooks" aria-label="Permalink to &quot;7. Lock the rules you can&#39;t break with hooks&quot;">​</a></h2><p>Claude follows CLAUDE.md instructions about 70% of the time. Hooks run as scripts at fixed points in the workflow and fire on 100% of runs. Save them for the rules you can&#39;t bend: auto-format after an edit, or block a push to main.</p><p>[圖 7]</p><hr><h2 id="_8-front-load-your-prompt" tabindex="-1">8. Front-load your prompt <a class="header-anchor" href="#_8-front-load-your-prompt" aria-label="Permalink to &quot;8. Front-load your prompt&quot;">​</a></h2><p>Claude Opus 4.8 reasons more after each of your turns, and that burns tokens. Pack the task and its constraints into your first message instead of drip-feeding them over many turns. You trade a dozen small exchanges for one big one: fewer round trips, lower cost, steadier work on long jobs.</p><p>[圖 8]</p><hr><h2 id="_9-reach-for-cli-tools" tabindex="-1">9. Reach for CLI tools <a class="header-anchor" href="#_9-reach-for-cli-tools" aria-label="Permalink to &quot;9. Reach for CLI tools&quot;">​</a></h2><p>CLI tools cost Claude the fewest tokens when it works with outside services. Install the gh CLI and Claude opens PRs and reads issues without tripping API rate limits. It also learns tools it doesn&#39;t know yet: point it at foo --help and let it work out the rest.</p><hr><h2 id="_10-let-claude-interview-you" tabindex="-1">10. Let Claude interview you <a class="header-anchor" href="#_10-let-claude-interview-you" aria-label="Permalink to &quot;10. Let Claude interview you&quot;">​</a></h2><p>For anything past a quick fix, flip the roles. Ask Claude to interview you about edge cases and tradeoffs before it writes a line, then have it save your answers to a SPEC.md. Start a fresh session and build from that spec. On the Console, the prompt improver runs the same polish over your prompts in under a minute.</p><hr><p>Do this and you spend your time reviewing Claude&#39;s work instead of redoing it. Like and repost if you found this helpful.</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：控制 Claude 讀到的內容、給它自我驗證的方式，是高效使用的兩大核心，10 個技巧從記憶檔到 CLI 工具全方位覆蓋。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>CLAUDE.md / Project 記憶</strong>：session 開頭載入，短而精準；每行問「刪掉 Claude 會犯錯嗎」，不會就刪</li><li><strong>Context 管理</strong>：換任務就 /clear，短乾淨 session &gt; 長雜亂 session；同一 bug 糾正兩次 → 清 context 重寫 prompt</li><li><strong>Explore → Plan → Code</strong>：先讓 Claude 讀檔寫計畫，再執行，避免直接 code 建錯方向</li><li><strong>Skills（.claude/skills/）</strong>：封裝慣例，Gotchas section 記錄真實錯誤，Anthropic 生產環境跑數百個</li><li><strong>Hooks vs CLAUDE.md</strong>：CLAUDE.md 遵循率 ~70%，Hooks 100%，關鍵不可違規則用 Hooks 鎖定</li><li><strong>反向採訪模式</strong>：讓 Claude 採訪你邊界案例後存 SPEC.md，再建 fresh session 依 spec 實作</li></ol><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>CLAUDE.md 遵循率：~70%；Hooks：100%（作者經驗估計）</li><li>Claude Opus 4.8：每輪推理消耗 tokens → 需要 front-load prompt</li><li>工具：<code>.claude/skills/</code>、<code>gh CLI</code>、<code>SPEC.md</code>、<code>/clear</code>、Plan Mode</li><li>來源：Anthropic 工程團隊與官方文件</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li>多數技巧是 Anthropic 官方最佳實踐的整理，創新性偏低，但品質一致且可直接套用</li><li>CLAUDE.md 70% vs Hooks 100% 的數字未提供明確來源，為作者經驗估計，實際遵循率可能因任務類型差異</li><li>技巧 10「讓 Claude 採訪你 + SPEC.md」是少見的反向工作流，對熟悉 Claude 的用戶有高實用性，但學習門檻略高</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>10 個技巧中 8 個可直接在此 workspace 套用，部分已在 CLAUDE.md 實踐</td></tr><tr><td>B. 創新性 (20%)</td><td>5/10</td><td>多數是官方最佳實踐整理，技巧 10（interview mode）有一定新穎性</td></tr><tr><td>C. 證據品質 (20%)</td><td>7/10</td><td>基於 Anthropic 工程團隊與文件，但 70%/100% 數字缺來源</td></tr><tr><td>D. 技術深度 (15%)</td><td>6/10</td><td>實用但偏淺，技術人員看完仍缺細節去完整實施</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>適用所有 Claude 使用者，非僅特定領域</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.2/10</strong></td><td>9×0.3+5×0.2+7×0.2+6×0.15+8×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：多條技巧直接對應現有 CLAUDE.md 規範（context 管理、skills、hooks、plan mode），可強化或驗證現有 workspace 規則集。</p>',59)])])}const f=t(r,[["render",i]]);export{p as __pageData,f as default};
